// ---- heatmap colorblind-safe perceptually-uniform ramp (cool->hot, NOT red/green) ----
function heatColor(v){ // v 0..1
  if (v<=0) return TOKENS.ecru;
  const stops = [
    [0.0,[242,241,234]],[0.15,[235,247,248]],[0.35,[0,183,195]],
    [0.55,[11,58,61]],[0.78,[204,102,68]],[1.0,[255,90,90]]
  ];
  let lo=stops[0], hi=stops[stops.length-1];
  for(let i=0;i<stops.length-1;i++){ if(v>=stops[i][0] && v<=stops[i+1][0]){lo=stops[i];hi=stops[i+1];break;} }
  const t = (v-lo[0])/((hi[0]-lo[0])||1);
  const c = lo[1].map((s,i)=> Math.round(s + (hi[1][i]-s)*t));
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}
function heatTextColor(v){ return v>0.45 && v<0.95 ? '#FFFFFF' : (v>=0.95?'#FFFFFF':TOKENS.ink); }
function sevGlyph(v){ return v>=0.9?'▲▲':v>=0.6?'▲':v>0.2?'◆':v>0?'·':'—'; }

