// build matrix: line x cause -> escalation count, normalized intensity
function buildMatrix(){
  const cellMap = {};
  const causeFor = (line,cause)=> {
    const key = line+'|'+cause; return cellMap[key] || (cellMap[key]={count:0});
  };
  // seed from known clusters/gaps
  const seed = {
    'Footwear|Sizing & Fit':312,'Footwear|Material Composition':0,'Footwear|Care & Maintenance':0,'Footwear|Compatibility':0,'Footwear|Specifications':54,
    'Apparel|Sizing & Fit':0,'Apparel|Material Composition':88,'Apparel|Care & Maintenance':39,'Apparel|Compatibility':0,'Apparel|Specifications':0,
    'Home|Sizing & Fit':0,'Home|Material Composition':33,'Home|Care & Maintenance':73,'Home|Compatibility':0,'Home|Specifications':0,
    'Outdoor|Sizing & Fit':18,'Outdoor|Material Composition':0,'Outdoor|Care & Maintenance':22,'Outdoor|Compatibility':67,'Outdoor|Specifications':15,
    'Electronics|Sizing & Fit':0,'Electronics|Material Composition':0,'Electronics|Care & Maintenance':0,'Electronics|Compatibility':89,'Electronics|Specifications':58
  };
  const max = Math.max(...Object.values(seed));
  const cells = {};
  PRODUCT_LINES.forEach(line=>ROOT_CAUSES.forEach(cause=>{
    const k = line+'|'+cause; const count = seed[k]||0;
    cells[k] = { line, cause, count, intensity: max? count/max : 0,
      wow_delta: count>0 ? (k==='Footwear|Sizing & Fit'? 142 : (count>40? Math.round(count*0.2): -Math.round(count*0.3))) : 0,
      patched: false };
  }));
  return cells;
}

