// ===================== REDUCER =====================
function reducer(state, action){
  switch(action.type){
    case 'SET_SCREEN': return {...state, activeScreen:action.screen};
    case 'MATRIX_LOADED': return {...state, matrixLoading:false};
    case 'SELECT_CELL': {
      return {...state, selectedCell:action.cell, activeScreen:'sku_drilldown', drilldownLoading:true};
    }
    case 'DRILLDOWN_LOADED': return {...state, drilldownLoading:false};
    case 'SET_SKU_SORT': return {...state, skuSort:action.sort};
    case 'SET_SKU_FILTER': return {...state, skuFilter:action.filter};
    case 'OPEN_CLUSTERS': return {...state, activeScreen:'cluster_view', clusterLoading:true};
    case 'CLUSTERS_LOADED': return {...state, clusterLoading:false};
    case 'SELECT_CLUSTER': return {...state, selectedCluster:action.cluster};
    case 'OPEN_REPLAY': return {...state, activeScreen:'replay_inspector', replay:{...state.replay, cluster:action.cluster, loading:true, step:0, confirmed:false}};
    case 'REPLAY_LOADED': return {...state, replay:{...state.replay, loading:false, skeletons:action.skeletons}};
    case 'REPLAY_STEP': return {...state, replay:{...state.replay, step:Math.min(state.replay.step+1, (state.replay.skeletons.length-1))}};
    case 'CONFIRM_CLUSTER': {
      const clusters = state.clusters.map(c=> c.cluster_id===action.clusterId? {...c, audited:true}:c);
      return {...state, clusters, replay:{...state.replay, confirmed:true}};
    }
    case 'OPEN_FIX_EDITOR': {
      const gap = action.gap || state.gaps.find(g=>g.cluster_id===(state.selectedCluster&&state.selectedCluster.cluster_id)) || state.gaps[0];
      return {...state, activeScreen:'fix_editor', activeGap:gap, activeSku:action.sku||state.activeSku,
        fixEditor:{...initialState.fixEditor, loading:true, bulkTarget:gap.affected_sku_count}};
    }
    case 'SUGGESTION_LOADED': return {...state, fixEditor:{...state.fixEditor, loading:false, suggestion:action.value, suggestionConf:action.conf, citation:action.citation, value:action.value, providerFallback:action.fallback||false}};
    case 'SET_FIX_VALUE': return {...state, fixEditor:{...state.fixEditor, value:action.value, validated:null}};
    case 'ACCEPT_SUGGESTION': return {...state, fixEditor:{...state.fixEditor, accepted:true, value:state.fixEditor.suggestion}};
    case 'TOGGLE_BULK': return {...state, fixEditor:{...state.fixEditor, bulkOn:action.on, forecastLoading:action.on}};
    case 'SET_BULK_COUNT': return {...state, fixEditor:{...state.fixEditor, bulkCount:action.count}};
    case 'FORECAST_LOADED': return {...state, fixEditor:{...state.fixEditor, forecastLoading:false, forecast:action.forecast}};
    case 'VALIDATED': return {...state, fixEditor:{...state.fixEditor, validated:action.result}};
    case 'SHIP_FIX': {
      const cell = state.selectedCell;
      let matrix = state.matrix;
      if(cell){ const k=cell.line+'|'+cell.cause; matrix = {...state.matrix, [k]:{...state.matrix[k], patched:true, intensity:Math.max(0,state.matrix[k].intensity*0.45)}}; }
      const newFix = { fix_id:'fix_'+(250+state.fixes.length), gap_id:state.activeGap.gap_id, attribute_name:state.activeGap.attribute_name,
        scope_sku_count:state.fixEditor.bulkOn?state.fixEditor.bulkTarget:1, applied_value:state.fixEditor.value, author:'Theo Vargas',
        status:'staged', forecast_deflection_delta:state.activeGap.projected_deflection_delta, realized_deflection_delta:null, shipped_date:null };
      return {...state, matrix, fixes:[newFix,...state.fixes], activeScreen:'heatmap_home',
        toast:(state.fixEditor.bulkOn?state.fixEditor.bulkTarget:1)+' SKU'+(state.fixEditor.bulkOn?'s':'')+' patched — tracking impact',
        fixEditor:{...state.fixEditor, shipped:true}};
    }
    case 'OPEN_SUPPLIER': return {...state, activeScreen:'supplier_composer', supplierPacket:{...state.supplierPacket, gap:action.gap||state.activeGap, loading:true, routed:false}};
    case 'SUPPLIER_LOADED': return {...state, supplierPacket:{...state.supplierPacket, loading:false, fields:action.fields, skuIds:action.skuIds, impact:action.impact}};
    case 'ROUTE_SUPPLIER': {
      const gaps = state.gaps.map(g=> g.gap_id===(state.supplierPacket.gap&&state.supplierPacket.gap.gap_id)? {...g, status:'supplier-pending'}:g);
      return {...state, gaps, supplierPacket:{...state.supplierPacket, routed:true}, activeScreen:'scorecard', toast:'Request packet routed to onboarding'};
    }
    case 'OPEN_TIMELINE': return {...state, activeScreen:'confidence_timeline', trendLoading:true};
    case 'TIMELINE_LOADED': return {...state, trendLoading:false};
    case 'SET_TREND_ATTR': return {...state, trendAttr:action.attr, selectedStepChange:null};
    case 'SELECT_STEP': return {...state, selectedStepChange:action.point};
    case 'OPEN_SCORECARD': return {...state, activeScreen:'scorecard', scorecard:{...state.scorecard, loading:true}};
    case 'NARRATIVE_LOADED': return {...state, scorecard:{...state.scorecard, loading:false, narrative:action.narrative}};
    case 'EXPORT_SCORECARD': return {...state, scorecard:{...state.scorecard, exported:true}, toast:'One-page briefing exported'};
    case 'OPEN_ALERTS': return {...state, activeScreen:'pattern_alert_inbox'};
    case 'DISMISS_ALERT': return {...state, alerts:state.alerts.filter(a=>a.alert_id!==action.id)};
    case 'TOGGLE_READONLY': return {...state, readOnly:!state.readOnly};
    case 'CLEAR_TOAST': return {...state, toast:null};
    default: return state;
  }
}

// ===================== AI HELPER (multi-provider fallback) =====================
async function aiCall(endpoint, payload, fallback){
  try{
    const r = await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    if(!r.ok) throw new Error('bad');
    const j = await r.json();
    return {ok:true, data:j, provider:'Gemini 3.1 Pro'};
  }catch(e){
    // graceful degradation -> deterministic fallback (session-21)
    return {ok:false, data:fallback, provider:'Claude Opus 4.7 (fallback)'};
  }
}

